--liquibase formatted sql

--changeset nexadrop:v162-taxonomia-completa runAlways:true
--comment La taxonomia no es la misma en todos los entornos: local tiene 1966 categorias, pre y pro 1964
--y desarrollo solo 41. Ninguna llego por una migracion —no hay un solo INSERT INTO category en todo el
--changelog—: en pre y pro las creo el consumidor del bus el 28-ago-2026 al ir entrando los productos, y
--en desarrollo, que tiene el bus sin consumir a proposito, nunca entro nada. Por eso las dos categorias
--de television, que no tienen ni productos ni descendientes con productos, no las arrastro ningun evento
--y se quedaron solo en local.
--Este cambio deja la taxonomia completa como dato del despliegue y no como efecto secundario del
--trafico: crea lo que falte, le pone su padre y sus ocho idiomas. Se apoya en el SLUG, que es unico y
--estable entre entornos.
--Va en tres pasos a proposito: primero las filas sin padre —asi no importa el orden entre padres e
--hijos—, despues el padre por su slug y por ultimo los nombres. ON CONFLICT en los dos INSERT y
--parent_id IS NULL en el UPDATE: no pisa nada de lo que ya haya, ni una traduccion corregida a mano ni
--una categoria recolgada en el panel.
--runAlways por lo mismo que el v161: lo que entre despues por el bus o por una carga queda completo en
--el siguiente despliegue, en vez de depender de que una migracion de una sola pasada llegue a tiempo.

-- 1) Las categorias que falten. Sin padre todavia: se resuelve en el paso 2 y asi da igual el orden.
INSERT INTO category (id, slug, source, external_id, name_zh, position, active, icon,
                      created_at, updated_at, created_by, updated_by)
